{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In mice, lapatinib brain-to-plasma concentration ratios after vascular correction were 0.013 and 0.028, demonstrating very low brain distribution for this 4-anilinoquinazoline kinase inhibitor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cediranib brain concentrations in wild-type mice were significantly lower than plasma, indicating restricted transport across the BBB for a closely related quinazoline-based kinase inhibitor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound (S)-22, a substituted quinazoline kinase inhibitor, had CSF exposure relative to free plasma of only 0.14 and was a P-gp substrate, showing limited brain access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "CZC25146, a kinase inhibitor with an anilino-heteroaryl core, showed negligible brain penetration with a total brain/plasma AUC ratio reported as negligible in mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "PET scans in patients showed lapatinib can penetrate the BBB, but this demonstrates only detectable brain uptake, not meaningful or adequate CNS exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a high-MW, polar, basic 4-anilinoquinazoline-like kinase inhibitor. The most transferable direct evidence from lapatinib, cediranib, (S)-22, and CZC25146 consistently shows very low brain/plasma or CSF/plasma ratios and efflux liability for this chemotype. The few positive signals, such as PET detection of lapatinib, reflect limited rather than meaningful CNS access. Therefore the prediction is fail.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic data for the exact query molecule.",
    "No human CNS exposure data for the query.",
    "Transporter phenotype of the query is not directly measured.",
    "Lapatinib clinical detection introduces some uncertainty, but the overall evidence indicates inadequate CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

